const p=$json;
const signals=[];
if(p.receives_leads) signals.push('receives_leads');
if(p.owner_sells) signals.push('owner_sells');
if(p.has_sales_team) signals.push('sales_team');
if(p.consultative_sale) signals.push('consultative_sale');
if(p.multiple_channels) signals.push('multiple_channels');
let score=0;
if(p.receives_leads) score+=20;
if(p.owner_sells) score+=10;
if(p.has_sales_team) score+=15;
if(p.consultative_sale) score+=20;
if(p.multiple_channels) score+=15;
return [{json:{...p,fit_score:score,fit_signals:signals,status:p.status||'new',source:p.source||'manual',next_action:'research_and_personalize'}}];
